export function createOverview(repo){let accountId=null,screen='me',items=[],selected=null,error=null;function snapshot(){return {accountId,screen,items:items.map(x=>({...x})),selected: selected?{...selected}:null,error}};return {snapshot,setAccount(id){accountId=typeof id==='string'&&id.trim()?id:null;screen='me';items=[];selected=null;error=null;return snapshot()},logout(){accountId=null;screen='me';items=[];selected=null;error=null;return snapshot()},showChat(){screen='chat';items=[];selected=null;error=null;return snapshot()},showMe(){screen='me';items=[];selected=null;error=null;return snapshot()},openList(){screen='list';items=[];selected=null;error=null;if(!accountId){error='unauthenticated';return snapshot()}let result;try{result=repo.listPatterns(accountId)}catch{result={ok:false,error:'unavailable'}}if(!result||!result.ok||!Array.isArray(result.data)){error=result?.error||'unavailable';return snapshot()}if(result.data.some(p=>p.accountId!==accountId||typeof p.patternId!=='string'||!p.patternId||typeof p.name!=='string'||typeof p.currentUnderstanding!=='string'||p.demoSource!=='synthetic'||!['candidate','confirmed','uncertain','rejected'].includes(p.decision))){error='unavailable';return snapshot()}items=result.data;return snapshot()},select(patternId){const item=items.find(p=>p.accountId===accountId&&p.patternId===patternId);if(!item||screen!=='list'){selected=null;error='not_found';return snapshot()}selected={accountId:item.accountId,patternId:item.patternId};screen='selection';error=null;return snapshot()}}}
